1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export type Step = QuoteStep | ClaimStep;
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Item {
14	  type: string;
15	  material?: string;
16	  enchantment?: number;
17	  cursed?: boolean;
18	}
19	
20	export interface ClaimStep {
21	  op: "claim";
22	  policy: number;
23	  incident: Incident;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export interface Damage {
32	  itemType: string;
33	  amount: number;
34	}
35	
36	export type Result = { premium: number } | { payout: number; remainingCap: number };
37	
38	const PROCESSING_FEE = 5;
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	/** Rounds up in the MHPCO's favor, ignoring binary floating-point noise. */
43	const roundPremium = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
44	
45	/** The closed set of insurable item types, each with its base premium in gold. */
46	const BASE_PREMIUMS = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	} as const satisfies Record<string, number>;
53	
54	export type ItemType = keyof typeof BASE_PREMIUMS;
55	
56	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type as ItemType];
57	
58	const quotePremium = (items: Item[]): number => {
59	  const basePremium = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
60	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
61	  return roundPremium(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
62	};
63	
64	const runStep = (step: Step): Result => {
65	  if (step.op === "quote") return { premium: quotePremium(step.items) };
66	  throw new Error(`Unsupported step: ${step.op}`);
67	};
68	
69	export const runScenario = (scenario: Scenario): { results: Result[] } => {
70	  return { results: scenario.steps.map(runStep) };
71	};
